    mcq1: ["Why were Israelites to love the sojourner according to Leviticus 19:34?", ["They were strangers in Egypt", "They were rich", "They were rulers", "They were priests"], 0, "They were once strangers."],
    mcq2: ["What does Romans 15:7 say?", ["Welcome one another as Christ has welcomed you", "Avoid strangers", "Welcome only friends", "Welcome for money"], 0, "Welcome as Christ welcomed you."],
